// Illustrative: people interpret repeated failures and choose how to improve the service.
checkout = team("Checkout")
releasePlatform = team("Release Platform")
releasePlatform.publish("Preview API", inputs, statuses, supportChannel)

requestId = checkout.requestPreview(commit)
preview = checkout.readPreviewStatus(requestId)
if preview.hasBuildError:
  checkout.inspectBuild(preview.error)

if preview.isReady:
  checkout.testCommit(preview.url)
  checkout.removePreview(requestId)

if blockedBranchRuns("payment stub") >= reviewAfterBlockedRuns:
  checkout.reportGap("payment stub", blockedRequestIds)

if releasePlatform.confirmsContractGap("payment stub"):
  tryTwoAppPreviewTogether(checkout, releasePlatform)
  releasePlatform.keepSupportingOneAppPreviews()

if checkout.canRunTwoAppPreviewFromDocs():
  releasePlatform.publishSupportedVersion()
  checkout.adoptOnItsSchedule()

