// Illustrative: RxJS carries the evidence. People decide whether to change who responds.
import { concatMap, filter, merge, scan, take } from 'rxjs';
const { reviewCases, trialDays } = example.parameters;
const customerReports$ = readStaleParcelReports$();

const decoderLogs$ = readCarrierDecoderRejects$();

const ticketHandoffs$ = readTrackingCarrierHandoffs$();
const matchedEvidence$ = merge(customerReports$, decoderLogs$, ticketHandoffs$).pipe(
  scan(matchSignalsByParcelId, emptyIncidentEvidence())
);

const trialResult$ = matchedEvidence$.pipe(
  filter(evidence => hasBouncedMatches(evidence, reviewCases)),
  take(1),
  concatMap(requestIncidentReview$),
  filter(review => review.approved),
  concatMap(review => runTriageTrial$(review, trialDays))
);

// The trial emits a summary when the window ends, including how many cases it saw.
const feedback$ = trialResult$.pipe(concatMap(returnToIncidentReview$));
feedback$.subscribe(recordTriageDecision);
